// Normalizes input URL and configuration options from Webhook or Manual Trigger
const firstItem = $input.first()?.json || {};
const body = firstItem.body || firstItem.query || firstItem;

// Default demo website if tested manually
let targetUrl = String(body.url || body.targetUrl || body.link || 'https://en.wikipedia.org/wiki/Web_scraping').trim();

if (!targetUrl.startsWith('http://') && !targetUrl.startsWith('https://')) {
  targetUrl = 'https://' + targetUrl;
}

// Note: the n8n Code-node sandbox has no global URL class, so parse with a regex.
const um = targetUrl.match(/^(https?:\/\/)([^\/?#]+)([^?#]*)/i);
if (!um) {
  throw new Error(`Invalid URL provided: "${targetUrl}"`);
}
const parsed = {
  origin: um[1].toLowerCase() + um[2].toLowerCase(),
  hostname: um[2].toLowerCase().replace(/:\d+$/, ''),
  pathname: um[3] || '/'
};

return [{
  json: {
    url: targetUrl,
    origin: parsed.origin,
    hostname: parsed.hostname,
    pathname: parsed.pathname,
    customSelector: body.selector || null,
    includeImages: body.includeImages !== false,
    includeLinks: body.includeLinks !== false,
    requestedAt: new Date().toISOString()
  }
}];

// Robust, pure-JS HTML parser and structured content extractor
const httpItem = $input.first()?.json || {};
const config = $('Parse Input & Configure').first()?.json || {};

const rawHtml = typeof httpItem.data === 'string' ? httpItem.data : (typeof httpItem === 'string' ? httpItem : (httpItem.body || ''));
const statusCode = httpItem.statusCode || (httpItem.error ? 500 : 200);

if (!rawHtml || httpItem.error) {
  return [{
    json: {
      success: false,
      url: config.url,
      statusCode: statusCode,
      error: httpItem.error || 'Empty HTML response or connection failure',
      scrapedAt: new Date().toISOString()
    }
  }];
}

// 1. Extract Page Title
const titleMatch = rawHtml.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const title = titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : '';

// 2. Extract Meta tags
const metaTags = {};
const ogTags = {};
const twitterTags = {};

const metaRegex = /<meta\s+([^>]+)>/gi;
let metaMatch;
while ((metaMatch = metaRegex.exec(rawHtml)) !== null) {
  const attrs = metaMatch[1];
  const nameMatch = attrs.match(/name=["']([^"']+)["']/i);
  const propMatch = attrs.match(/property=["']([^"']+)["']/i);
  const contentMatch = attrs.match(/content=["']([\s\S]*?)["']/i);

  const name = (nameMatch ? nameMatch[1] : '').toLowerCase();
  const prop = (propMatch ? propMatch[1] : '').toLowerCase();
  const content = contentMatch ? contentMatch[1].trim() : '';

  if (name) {
    if (name.startsWith('twitter:')) {
      twitterTags[name.replace('twitter:', '')] = content;
    } else {
      metaTags[name] = content;
    }
  }
  if (prop) {
    if (prop.startsWith('og:')) {
      ogTags[prop.replace('og:', '')] = content;
    } else if (prop.startsWith('twitter:')) {
      twitterTags[prop.replace('twitter:', '')] = content;
    }
  }
}

// Canonical link
const canonicalMatch = rawHtml.match(/<link[^>]+rel=["']canonical["'][^>]+href=["']([^"']+)["'][^>]*>/i);
const canonicalUrl = canonicalMatch ? canonicalMatch[1] : config.url;

// 3. Extract Headings
const headings = [];
const headingRegex = /<(h[1-6])[^>]*>([\s\S]*?)<\/\1>/gi;
let hMatch;
while ((hMatch = headingRegex.exec(rawHtml)) !== null) {
  const level = parseInt(hMatch[1].substring(1), 10);
  const text = hMatch[2].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  if (text) {
    headings.push({ level, text });
  }
}

// 4. Extract Links
const links = [];
const linkRegex = /<a\s+[^>]*href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
let aMatch;
while ((aMatch = linkRegex.exec(rawHtml)) !== null) {
  const href = aMatch[1].trim();
  const text = aMatch[2].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  if (!href.startsWith('javascript:') && !href.startsWith('mailto:') && !href.startsWith('tel:')) {
    let resolvedHref = href;
    // No global URL class in the Code-node sandbox: resolve relative links by hand.
    if (/^https?:\/\//i.test(href)) {
      resolvedHref = href;
    } else if (href.startsWith('//')) {
      resolvedHref = config.url.split('//')[0] + href;
    } else if (href.startsWith('/')) {
      resolvedHref = config.origin + href;
    } else {
      resolvedHref = config.url.split(/[?#]/)[0].replace(/[^\/]*$/, '') + href;
    }
    const isInternal = resolvedHref.startsWith(config.origin);
    links.push({ text: text || resolvedHref, href: resolvedHref, isInternal });
  }
}

// 5. Clean HTML for content extraction
let cleanContent = rawHtml;
// Remove scripts, styles, noscript, svg, iframes, nav, footer, header
cleanContent = cleanContent.replace(/<script[\s\S]*?<\/script>/gi, '');
cleanContent = cleanContent.replace(/<style[\s\S]*?<\/style>/gi, '');
cleanContent = cleanContent.replace(/<noscript[\s\S]*?<\/noscript>/gi, '');
cleanContent = cleanContent.replace(/<svg[\s\S]*?<\/svg>/gi, '');
cleanContent = cleanContent.replace(/<iframe[\s\S]*?<\/iframe>/gi, '');
cleanContent = cleanContent.replace(/<nav[\s\S]*?<\/nav>/gi, '');
cleanContent = cleanContent.replace(/<footer[\s\S]*?<\/footer>/gi, '');
cleanContent = cleanContent.replace(/<header[\s\S]*?<\/header>/gi, '');
cleanContent = cleanContent.replace(/<!--[\s\S]*?-->/g, '');

// Convert headings to Markdown
cleanContent = cleanContent.replace(/<h1[^>]*>([\s\S]*?)<\/h1>/gi, '\n\n# $1\n\n');
cleanContent = cleanContent.replace(/<h2[^>]*>([\s\S]*?)<\/h2>/gi, '\n\n## $1\n\n');
cleanContent = cleanContent.replace(/<h3[^>]*>([\s\S]*?)<\/h3>/gi, '\n\n### $1\n\n');
cleanContent = cleanContent.replace(/<h[4-6][^>]*>([\s\S]*?)<\/h[4-6]>/gi, '\n\n#### $1\n\n');

// Convert lists & blockquotes
cleanContent = cleanContent.replace(/<li[^>]*>([\s\S]*?)<\/li>/gi, '\n* $1');
cleanContent = cleanContent.replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi, '\n> $1\n');
cleanContent = cleanContent.replace(/<p[^>]*>([\s\S]*?)<\/p>/gi, '\n\n$1\n\n');
cleanContent = cleanContent.replace(/<br\s*\/?>/gi, '\n');

// Strip remaining tags
let markdown = cleanContent.replace(/<[^>]+>/g, ' ');
markdown = markdown.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"');
markdown = markdown.split('\n').map(l => l.trim()).filter(l => l.length > 0).join('\n\n');

// Plain text
const plainText = markdown.replace(/#+\s*/g, '').replace(/\*\s*/g, '').replace(/>\s*/g, '');
const words = (plainText.match(/\b\w+\b/g) || []);
const wordCount = words.length;
const readingTimeMinutes = Math.max(1, Math.round(wordCount / 200));

const internalLinks = links.filter(l => l.isInternal);
const externalLinks = links.filter(l => !l.isInternal);

return [{
  json: {
    success: true,
    url: config.url,
    statusCode: statusCode,
    title: title || ogTags.title || '',
    metadata: {
      description: metaTags.description || ogTags.description || '',
      keywords: metaTags.keywords || '',
      author: metaTags.author || '',
      canonical: canonicalUrl,
      openGraph: ogTags,
      twitterCard: twitterTags
    },
    headings: headings,
    links: {
      total: links.length,
      internalCount: internalLinks.length,
      externalCount: externalLinks.length,
      internal: internalLinks.slice(0, 50),
      external: externalLinks.slice(0, 50)
    },
    statistics: {
      wordCount: wordCount,
      characterCount: plainText.length,
      readingTimeMinutes: readingTimeMinutes
    },
    cleanMarkdown: markdown,
    cleanText: plainText,
    scrapedAt: new Date().toISOString()
  }
}];
